import { jev } from "../../core/client.ts";
import { validateQuestions, type Answer, type Questions, type State } from "../../core/types.ts";
import { FileStateError, readFileState } from "../level08/read-state.ts";
import { expandPatterns, pruneFiles, type Skipped } from "./prune.ts";

export type Decide = (state: State, questions: Questions) => Promise<{ answers: Record<string, Answer>; usage?: unknown }>;

export interface FileAnswers {
  path: string;
  answers: Record<string, Answer>;
  usage?: unknown;
}

export interface AskFilesResult {
  results: FileAnswers[];
  skipped: Skipped[];
  calls: number;
}

export function parseQuestions(questionsJson: string): Questions {
  let parsed: unknown;
  try {
    parsed = JSON.parse(questionsJson);
  } catch (err: any) {
    throw new Error(`questions_json is not valid JSON: ${err.message}`);
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("questions_json must be an object keyed by question id");
  validateQuestions(parsed as Questions);
  return parsed as Questions;
}

export async function parallel<T, R>(items: T[], limit: number, fn: (item: T) => Promise<R>): Promise<R[]> {
  const out: R[] = new Array(items.length);
  let next = 0;
  const worker = async () => {
    while (next < items.length) {
      const i = next++;
      out[i] = await fn(items[i]);
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  return out;
}

export async function askFiles(
  patterns: string[],
  questionsJson: string,
  cwd: string,
  opts: { recursive?: boolean; concurrency?: number; decide?: Decide; onResult?: (r: FileAnswers) => void } = {},
): Promise<AskFilesResult> {
  const questions = parseQuestions(questionsJson);
  const decide = opts.decide ?? ((s, q) => jev.systemOne(s, q));
  const expanded = await expandPatterns(patterns, cwd, opts.recursive ?? false);
  const { files, skipped } = await pruneFiles(expanded, cwd);
  const results: FileAnswers[] = [];
  await parallel(files, opts.concurrency ?? 16, async (path) => {
    try {
      const state = await readFileState(path, cwd);
      const { answers, usage } = await decide(state, questions);
      const r = { path, answers, usage };
      results.push(r);
      opts.onResult?.(r);
    } catch (err: any) {
      skipped.push({ path, reason: err instanceof FileStateError ? err.message : `call failed: ${err?.message ?? err}` });
    }
  });
  results.sort((a, b) => a.path.localeCompare(b.path));
  return { results, skipped, calls: results.length };
}

import { glob, stat } from "node:fs/promises";
import { isAbsolute, relative, resolve, sep } from "node:path";
import { LIMITS } from "../../core/types.ts";
import { MAX_FILE_CHARS } from "../level08/read-state.ts";

export const SKIP_DIRS = new Set(["node_modules", ".git", ".sessions", "dist", "build", "coverage", ".pi"]);
const GLOB_CHARS = /[*?[\]{}]/;

export interface Skipped {
  path: string;
  reason: string;
}

export async function expandPatterns(patterns: string[], cwd: string, recursive: boolean): Promise<string[]> {
  const out = new Set<string>();
  for (const raw of patterns) {
    const pattern = raw.trim();
    if (!pattern) continue;
    if (GLOB_CHARS.test(pattern)) {
      for await (const p of glob(pattern, { cwd })) out.add(String(p));
      continue;
    }
    const full = isAbsolute(pattern) ? pattern : resolve(cwd, pattern);
    let info;
    try { info = await stat(full); } catch { out.add(pattern); continue; } // let prune report it
    if (info.isFile()) { out.add(pattern); continue; }
    for await (const p of glob(recursive ? `${pattern.replace(/\/+$/, "")}/**/*` : `${pattern.replace(/\/+$/, "")}/*`, { cwd })) out.add(String(p));
  }
  return [...out].sort();
}

export async function pruneFiles(paths: string[], cwd: string, cap = LIMITS.MAX_CHOICE_OPTIONS): Promise<{ files: string[]; skipped: Skipped[] }> {
  const files: string[] = [];
  const skipped: Skipped[] = [];
  for (const path of paths) {
    const full = isAbsolute(path) ? path : resolve(cwd, path);
    const rel = relative(cwd, full);
    if (rel.startsWith("..")) { skipped.push({ path, reason: "outside the repo" }); continue; }
    if (rel.split(sep).some((part) => SKIP_DIRS.has(part))) { skipped.push({ path, reason: "skipped directory" }); continue; }
    let info;
    try { info = await stat(full); } catch { skipped.push({ path, reason: "not found" }); continue; }
    if (!info.isFile()) continue;
    if (info.size === 0) { skipped.push({ path, reason: "empty" }); continue; }
    if (info.size > MAX_FILE_CHARS) { skipped.push({ path, reason: `too large, ${info.size} bytes` }); continue; }
    if (/\.(png|jpe?g|gif|webp|ico|pdf|zip|gz|tgz|woff2?|ttf|mp[34]|mov|lock)$/i.test(path)) { skipped.push({ path, reason: "binary or lock file" }); continue; }
    if (files.length >= cap) { skipped.push({ path, reason: `over the ${cap} file cap; narrow the pattern` }); continue; }
    files.push(path);
  }
  return { files, skipped };
}

import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import { LIMITS, type ChoiceAnswer } from "../../core/types.ts";
import type { Decide } from "./ask-files.ts";

export interface Candidate {
  path: string;
  note?: string;
}

export interface FirstPick {
  path: string | null;
  confidence: number;
  probabilities: Record<string, number>;
}

export function pickQuestion(question: string, candidates: Candidate[]) {
  const criteria: Record<string, string | null> = {};
  for (const c of candidates.slice(0, LIMITS.MAX_CHOICE_OPTIONS - 1)) criteria[c.path] = c.note ?? null;
  criteria.none = "No file in the list fits";
  return { pick: choice(question, criteria) };
}

export async function pickFirstFile(question: string, candidates: Candidate[], decide: Decide = (s, q) => jev.systemOne(s, q), floor = 0.3): Promise<FirstPick> {
  if (!candidates.length) return { path: null, confidence: 0, probabilities: {} };
  const state = { question, files: candidates.map((c) => c.path) };
  const { answers } = await decide(state, pickQuestion(question, candidates));
  const a = answers.pick as ChoiceAnswer;
  const path = a.choice === "none" || a.confidence < floor ? null : a.choice;
  return { path, confidence: a.confidence, probabilities: a.probabilities };
}
